"""Wi-Fi Vision YOLO Controller (PC)"""
import cv2
import requests
from ultralytics import YOLO

ESP_IP = "192.168.0.50"  # ESP32 IP
model = YOLO("yolov8n.pt")
cap = cv2.VideoCapture(f"http://{ESP_IP}:8080/")

while cap.isOpened():
    ret, frame = cap.read()
    if not ret:
        break

    results = model(frame, verbose=False)
    person = any(int(b.cls[0]) == 0 for r in results for b in r.boxes)

    cmd = "STOP" if person else "GO"
    try:
        requests.get(f"http://{ESP_IP}:8080/ai?action={cmd}", timeout=0.1)
    except Exception:
        pass

    cv2.imshow("ESPZero YOLO", results[0].plot())
    if cv2.waitKey(1) & 0xFF == ord("q"):
        break

cap.release()
cv2.destroyAllWindows()
